29:   function ensureAudio() {
30:     if (!audioContext) {
31:       const Context = window.AudioContext || window.webkitAudioContext;
32:       if (!Context) throw new Error('Este navegador no tiene Web Audio API.');
33:       audioContext = new Context({ latencyHint: 'interactive' });
34:       for (const id of ['a', 'b']) createDeck(id);
35:     }
36:     if (audioContext.state === 'suspended') audioContext.resume();
37:     return audioContext;
