40:   function createDeck(id) {
41:     const audio = $(`#audio-${id}`);
42:     const source = audioContext.createMediaElementSource(audio);
43:     const low = audioContext.createBiquadFilter();
44:     const mid = audioContext.createBiquadFilter();
45:     const high = audioContext.createBiquadFilter();
46:     low.type = 'lowshelf'; low.frequency.value = 100;
47:     mid.type = 'peaking'; mid.frequency.value = 2500; mid.Q.value = 0.8;
48:     high.type = 'highshelf'; high.frequency.value = 12000;
49:     const volume = audioContext.createGain();
50:     const cross = audioContext.createGain();
51:     const analyser = audioContext.createAnalyser();
52:     analyser.fftSize = 1024;
53:     analyser.smoothingTimeConstant = 0.82;
54:     source.connect(low).connect(mid).connect(high).connect(volume).connect(cross).connect(analyser).connect(audioContext.destination);
55:     decks[id] = {
56:       id, audio, source, filters: { low, mid, high }, volume, cross, analyser,
57:       data: new Uint8Array(analyser.frequencyBinCount), bpm: id === 'a' ? 120 : 124,
58:       baseBpm: id === 'a' ? 120 : 124, pitch: 0, objectUrl: null, trackName: '', artist: '',
59:       demo: false, cuePoint: 0, lastPhase: 0
60:     };
61:   }
