63:   function setCrossfader(value) {
64:     crossPosition = Number(value) / 100;
65:     $('#crossfader').value = value;
66:     if (!audioContext) return;
67:     // Equal-power curve: constant perceived loudness through the center.
68:     decks.a.cross.gain.setTargetAtTime(Math.cos(crossPosition * Math.PI / 2), audioContext.currentTime, 0.015);
69:     decks.b.cross.gain.setTargetAtTime(Math.sin(crossPosition * Math.PI / 2), audioContext.currentTime, 0.015);
70:   }
