106:   function addToLibrary(track) {
107:     const existing = library.findIndex(item => item.name === track.name && item.source === track.source);
108:     const entry = {
109:       id: track.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
110:       name: track.name,
111:       artist: track.artist || (track.demo ? 'DJ Lab' : 'Audio local'),
112:       bpm: Number(track.bpm) || null,
