114:       source: track.source || (track.demo ? 'Demo' : 'Local'),
115:       kind: track.demo ? 'demo' : 'local'
116:     };
117:     if (existing >= 0) library[existing] = entry; else library.unshift(entry);
118:     persistLibrary();
