122:   function makeDemoWav(bpm, seed) {
123:     const sampleRate = 22050;
124:     const beat = 60 / bpm;
125:     const beatCount = 16;
126:     const length = Math.ceil(sampleRate * beat * beatCount);
127:     const samples = new Float32Array(length);
128:     let state = seed >>> 0;
129:     const random = () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
130:     for (let b = 0; b < beatCount; b++) {
131:       const start = Math.floor(b * beat * sampleRate);
132:       const kickLength = Math.floor(sampleRate * 0.24);
133:       for (let i = 0; i < kickLength && start + i < length; i++) {
134:         const t = i / sampleRate;
135:         const env = Math.exp(-t * 17);
136:         const freq = 43 + 75 * Math.exp(-t * 28);
137:         samples[start + i] += Math.sin(2 * Math.PI * freq * t) * env * 0.78;
138:       }
139:       if (b % 4 === 1 || b % 4 === 3) {
140:         const clapStart = start + Math.floor(sampleRate * beat * 0.12);
141:         for (let i = 0; i < sampleRate * 0.15 && clapStart + i < length; i++) {
142:           const t = i / sampleRate;
143:           samples[clapStart + i] += (random() * 2 - 1) * Math.exp(-t * 24) * 0.17;
144:         }
145:       }
146:       const hatStart = start + Math.floor(sampleRate * beat * 0.5);
147:       for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
148:         const t = i / sampleRate;
149:         samples[hatStart + i] += (random() * 2 - 1) * Math.exp(-t * 75) * 0.08;
150:       }
151:     }
152:     const buffer = new ArrayBuffer(44 + samples.length * 2);
153:     const view = new DataView(buffer);
154:     const write = (offset, text) => [...text].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
155:     write(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); write(8, 'WAVE');
156:     write(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
157:     view.setUint16(22, 1, true); view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true);
158:     view.setUint16(32, 2, true); view.setUint16(34, 16, true); write(36, 'data');
159:     view.setUint32(40, samples.length * 2, true);
160:     for (let i = 0; i < samples.length; i++) view.setInt16(44 + i * 2, Math.max(-1, Math.min(1, samples[i])) * 32767, true);
161:     return new Blob([buffer], { type: 'audio/wav' });
162:   }
