164:   function startDemo(id) {
165:     const bpm = id === 'a' ? 120 : 124;
166:     const name = id === 'a' ? 'Neon pulse · 01' : 'Afterglow · 02';
167:     const blob = makeDemoWav(bpm, id === 'a' ? 17 : 29);
168:     attachTrack(id, URL.createObjectURL(blob), { name, artist: 'DJ Lab · demo generativa', bpm, duration: 60 / bpm * 16, demo: true, loop: true });
169:     playDeck(id);
170:     toast(`Demo ${id.toUpperCase()} lista · ${bpm} BPM`);
171:   }
