173:   async function playDeck(id) {
174:     try {
175:       ensureAudio();
176:       const deck = decks[id];
177:       if (!deck.audio.src) { toast('Carga una pista o inicia la demo primero.'); return; }
178:       if (deck.audio.paused) await deck.audio.play(); else deck.audio.pause();
179:       updateTransport(id);
180:       setStatus(deck.audio.paused ? 'AUDIO PREPARADO' : 'REPRODUCIENDO');
181:       updatePhase();
182:     } catch (error) {
183:       toast(error.message || 'No se pudo iniciar el audio.');
184:     }
185:   }
