187:   function updateTransport(id) {
188:     const button = $(`.play-button[data-deck="${id}"]`);
189:     if (!button) return;
190:     const playing = Boolean(decks[id]?.audio && !decks[id].audio.paused);
191:     button.textContent = playing ? 'Ⅱ' : '▶';
192:     button.classList.toggle('is-playing', playing);
193:     button.setAttribute('aria-label', `${playing ? 'Pausar' : 'Reproducir'} Deck ${id.toUpperCase()}`);
194:   }
