196:   function syncDeck(id) {
197:     ensureAudio();
198:     const deck = decks[id];
199:     const target = id === 'a' ? decks.b.bpm : decks.a.bpm;
200:     deck.pitch = Math.max(-8, Math.min(8, (target / deck.baseBpm - 1) * 100));
201:     $(`[data-pitch="${id}"]`).value = deck.pitch;
202:     setPitch(id, deck.pitch);
203:     if (decks.a.audio.src && decks.b.audio.src) {
204:       const master = decks.a.audio.currentTime || 0;
205:       deck.audio.currentTime = master;
206:     }
207:     toast(`Deck ${id.toUpperCase()} sincronizado a ${target.toFixed(1)} BPM`);
208:   }
209: 
210:   function cueDeck(id) {
211:     const deck = decks[id];
212:     if (!deck?.audio.src) { toast('Carga una pista antes de marcar CUE.'); return; }
213:     deck.audio.pause();
214:     deck.audio.currentTime = deck.cuePoint;
215:     updateTransport(id);
216:   }
