218:   function formatTime(seconds) {
219:     if (!Number.isFinite(seconds)) return '00:00';
220:     const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
221:     const secs = Math.floor(seconds % 60).toString().padStart(2, '0');
222:     return `${mins}:${secs}`;
223:   }
224: 
225:   function renderWave(id) {
226:     const deck = decks[id];
227:     const canvas = $(`#wave-${id}`);
228:     const ctx = canvas.getContext('2d');
229:     const width = canvas.clientWidth || 500;
230:     const height = canvas.clientHeight || 67;
231:     const ratio = Math.min(window.devicePixelRatio || 1, 2);
232:     if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) {
233:       canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio);
234:     }
235:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
236:     ctx.clearRect(0, 0, width, height);
237:     ctx.fillStyle = '#0c1016'; ctx.fillRect(0, 0, width, height);
238:     ctx.strokeStyle = '#202630'; ctx.lineWidth = 1;
239:     ctx.beginPath(); ctx.moveTo(0, height / 2); ctx.lineTo(width, height / 2); ctx.stroke();
240:     const colors = ['#fa596d', '#72e294', '#57aef4'];
241:     const bands = [[0, 250], [250, 4000], [4000, 12000]];
242:     const sampleRate = audioContext?.sampleRate || 44100;
243:     const bins = deck.data.length;
244:     const maxHz = sampleRate / 2;
245:     const active = Boolean(deck.analyser && !deck.audio.paused && deck.audio.src);
246:     if (active) deck.analyser.getByteFrequencyData(deck.data);
247:     const columns = Math.max(1, Math.floor(width / 3));
248:     const offset = deck.audio.currentTime ? Math.floor(deck.audio.currentTime * 14) % columns : 0;
249:     for (let x = 0; x < columns; x++) {
250:       const pos = (x + offset) % columns;
251:       let total = 0;
252:       for (let band = 0; band < bands.length; band++) {
253:         const [lo, hi] = bands[band];
254:         const start = Math.max(0, Math.floor(lo / maxHz * bins));
255:         const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
256:         let energy = 0;
257:         if (active) {
258:           for (let i = start; i < end; i++) energy += deck.data[i];
259:           energy /= (end - start) * 255;
260:         } else {
261:           const wave = Math.sin((pos * 0.083) + band * 1.7 + (id === 'b' ? 0.8 : 0));
262:           energy = deck.audio.src ? 0.12 + Math.abs(wave) * 0.2 : 0.035;
263:         }
264:         const barHeight = Math.max(2, energy * height * 0.75);
265:         const alpha = active ? 0.42 + Math.min(0.55, energy) : 0.20;
266:         ctx.globalAlpha = alpha;
267:         ctx.fillStyle = colors[band];
268:         const yOffset = band === 0 ? -1 : band === 1 ? 0 : 1;
269:         ctx.fillRect(pos * 3, (height - barHeight) / 2 + yOffset * 5, 2, barHeight);
270:         total += energy;
271:       }
272:       if (active && total > 0.14) {
273:         ctx.globalAlpha = 0.25;
274:         ctx.fillStyle = id === 'a' ? '#54e3dc' : '#ff4e97';
275:         ctx.fillRect(pos * 3, 0, 1, height);
276:       }
277:     }
278:     ctx.globalAlpha = 1;
279:     const progress = deck.audio.duration ? deck.audio.currentTime / deck.audio.duration : 0;
280:     const playX = progress * width;
281:     ctx.fillStyle = id === 'a' ? '#dcfff9' : '#ffe0ed';
282:     ctx.shadowColor = id === 'a' ? '#54e3dc' : '#ff4e97'; ctx.shadowBlur = 7;
283:     ctx.fillRect(playX, 0, 1, height); ctx.shadowBlur = 0;
284:     $(`#time-${id}`).textContent = `${formatTime(deck.audio.currentTime || 0)} / ${formatTime(deck.audio.duration)}`;
285:   }
