287:   function updatePhase() {
288:     if (!decks.a || !decks.b) return;
289:     const a = decks.a, b = decks.b;
290:     const beatsA = a.audio.currentTime * a.bpm / 60;
291:     const beatsB = b.audio.currentTime * b.bpm / 60;
292:     const phaseA = ((beatsA % 1) + 1) % 1;
293:     const phaseB = ((beatsB % 1) + 1) % 1;
294:     let delta = Math.abs(phaseA - phaseB) * 60000 / Math.max(a.bpm, 1);
295:     delta = Math.min(delta, 60000 / Math.max(a.bpm, 1) - delta);
296:     $('#phase-readout').textContent = a.audio.src && b.audio.src ? `FASE ${Math.round(delta)} MS` : 'FASE —';
297:   }
298: 
299:   function checkMix() {
300:     ensureAudio();
301:     const a = decks.a, b = decks.b;
302:     const card = $('#score-card');
303:     if (!a.audio.src || !b.audio.src) {
304:       card.className = 'score-card bad'; $('#score-title').textContent = 'FALTAN PISTAS';
305:       $('#score-message').textContent = 'Carga o inicia las demos en ambos decks.'; $('#score-value').textContent = '—'; return;
306:     }
307:     const bpmDifference = Math.abs(b.bpm - TARGET_BPM);
308:     if (!a.audio.paused && !b.audio.paused) {
309:       const phaseA = ((a.audio.currentTime * a.bpm / 60) % 1 + 1) % 1;
310:       const phaseB = ((b.audio.currentTime * b.bpm / 60) % 1 + 1) % 1;
311:       let diff = Math.abs(phaseA - phaseB) * 60000 / TARGET_BPM;
312:       diff = Math.min(diff, 60000 / TARGET_BPM - diff);
313:       const result = diff < 30 ? 'PERFECT' : diff < 70 ? 'GOOD' : 'DESINCRONIZADO';
314:       card.className = `score-card ${result === 'PERFECT' ? 'good' : result === 'GOOD' ? '' : 'bad'}`;
315:       $('#score-title').textContent = result === 'DESINCRONIZADO' ? result : `${result} · BEATMATCH`;
316:       $('#score-message').textContent = result === 'PERFECT' ? 'Fase alineada. ¡Mezcla limpia!' : result === 'GOOD' ? 'Muy cerca. Ajusta el jog imaginario.' : 'Desfase detectado. Pulsa SYNC y prueba otra vez.';
317:       $('#score-value').textContent = `${Math.round(diff)} ms`;
318:       $('#phase-readout').textContent = `FASE ${Math.round(diff)} MS`;
319:     } else if (bpmDifference <= 0.5) {
320:       card.className = 'score-card good'; $('#score-title').textContent = 'TEMPO ALINEADO';
321:       $('#score-message').textContent = 'Ahora reproduce ambos decks para comprobar la fase.';
322:       $('#score-value').textContent = `${b.bpm.toFixed(1)} BPM`;
323:     } else {
324:       card.className = 'score-card bad'; $('#score-title').textContent = 'AJUSTA EL PITCH';
325:       $('#score-message').textContent = `Lleva el Deck B de ${b.bpm.toFixed(1)} a ${TARGET_BPM} BPM.`;
326:       $('#score-value').textContent = `${(b.bpm - TARGET_BPM > 0 ? '+' : '')}${(b.bpm - TARGET_BPM).toFixed(1)}`;
327:     }
328:   }
