337:   function renderLibrary() {
338:     const body = $('#library-body');
339:     $('#library-count').textContent = `${library.length} ${library.length === 1 ? 'pista' : 'pistas'}`;
340:     if (!library.length) {
341:       body.innerHTML = '<tr class="empty-row"><td colspan="5"><span>♫</span><strong>Tu biblioteca empieza acá</strong><small>Inicia una demo o carga archivos de audio desde tu dispositivo.</small></td></tr>';
342:       return;
343:     }
344:     body.replaceChildren(...library.slice(0, 20).map(track => {
345:       const row = document.createElement('tr');
346:       const name = document.createElement('td'); name.innerHTML = `<div class="library-track"><i>♪</i><span><b></b><small></small></span></div>`;
347:       name.querySelector('b').textContent = track.name; name.querySelector('small').textContent = track.artist || track.source;
348:       const duration = document.createElement('td'); duration.textContent = formatTime(track.duration || 0);
349:       const bpm = document.createElement('td'); bpm.textContent = track.bpm ? Number(track.bpm).toFixed(1) : '—';
350:       const source = document.createElement('td'); source.textContent = track.source || 'Local';
351:       const action = document.createElement('td');
352:       const loadA = document.createElement('button'); loadA.className = 'table-load'; loadA.textContent = 'A'; loadA.title = 'Cargar en Deck A';
353:       const loadB = document.createElement('button'); loadB.className = 'table-load'; loadB.textContent = 'B'; loadB.title = 'Cargar en Deck B';
354:       loadA.addEventListener('click', () => loadLibraryTrack(track, 'a')); loadB.addEventListener('click', () => loadLibraryTrack(track, 'b'));
355:       action.append(loadA, document.createTextNode(' '), loadB); row.append(name, duration, bpm, source, action); return row;
356:     }));
357:   }
