359:   function loadLibraryTrack(track, id) {
360:     if (track.kind === 'demo') {
361:       startDemo(id);
362:       return;
363:     }
364:     const picker = document.createElement('input'); picker.type = 'file'; picker.accept = 'audio/*';
365:     picker.addEventListener('change', () => {
366:       const file = picker.files?.[0];
367:       if (file) loadLocalFile(file, id);
368:     }, { once: true });
369:     picker.click();
370:     toast('Vuelve a elegir el archivo: el navegador no guarda el audio en la biblioteca.');
371:   }
