373:   function loadLocalFile(file, id) {
374:     if (!file.type.startsWith('audio/')) { toast('Elige un archivo de audio compatible.'); return; }
375:     const url = URL.createObjectURL(file);
376:     attachTrack(id, url, { name: file.name.replace(/\.[^.]+$/, ''), artist: 'Archivo local · solo este dispositivo', duration: 0, bpm: id === 'a' ? 120 : 124, demo: false, loop: false });
377:     const deck = decks[id];
378:     deck.audio.onloadedmetadata = () => {
379:       const entry = library.find(item => item.name === deck.trackName && item.source === 'Local');
380:       if (entry) { entry.duration = deck.audio.duration || 0; persistLibrary(); renderLibrary(); }
381:     };
382:     toast(`Audio local cargado en Deck ${id.toUpperCase()}`);
383:   }
