385:   async function enableMidi() {
386:     if (!navigator.requestMIDIAccess) { toast('WebMIDI no está disponible en este navegador.'); return; }
387:     try {
388:       midiAccess = await navigator.requestMIDIAccess();
389:       for (const input of midiAccess.inputs.values()) input.onmidimessage = handleMidi;
390:       midiAccess.onstatechange = () => {
391:         for (const input of midiAccess.inputs.values()) input.onmidimessage = handleMidi;
392:         refreshMidiState();
393:       };
394:       refreshMidiState();
395:       toast(midiAccess.inputs.size ? 'Controladora MIDI conectada.' : 'MIDI listo: conecta una controladora.');
396:     } catch { toast('No se concedió acceso MIDI. Puedes mezclar con controles táctiles.'); }
397:   }
