399:   function refreshMidiState() {
400:     const connected = Boolean(midiAccess && midiAccess.inputs.size);
401:     $('#midi-state').textContent = connected ? 'ON' : 'LISTO';
402:     $('#midi-button').classList.toggle('midi-active', connected);
403:   }
