405:   function handleMidi(event) {
406:     const [status, data1, data2] = event.data;
407:     const command = status & 0xf0;
408:     const channel = status & 0x0f;
409:     if ((command === 0x90 || command === 0x80) && data2 > 0) {
410:       // Standard channel-1 notes: 60 toggles Deck A, 61 toggles Deck B.
411:       if (channel === 0 && data1 === 60) playDeck('a');
412:       if (channel === 0 && data1 === 61) playDeck('b');
413:       return;
414:     }
415:     if (command === 0xb0) {
